"use client";

import "./checkbox-group.css";

import type React from "react";

import { CheckboxGroup as BaseCheckboxGroup } from "@base-ui/react/checkbox-group";
import { cn } from "tailwind-variants";

import { CheckboxGroupContext } from "./checkbox-group.context";
import { checkboxGroupVariants, type CheckboxGroupVariants } from "./checkbox-group.variants";

export type CheckboxGroupProps = CheckboxGroupVariants &
  React.ComponentProps<typeof BaseCheckboxGroup>;

export const CheckboxGroupRoot = ({
  children,
  className,
  orientation,
  ...props
}: CheckboxGroupProps) => {
  const slots = checkboxGroupVariants({ orientation });

  return (
    <CheckboxGroupContext.Provider value={{ slots }}>
      <BaseCheckboxGroup className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseCheckboxGroup>
    </CheckboxGroupContext.Provider>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const checkboxGroupVariants = tv({
  slots: {
    root: "checkbox-group",
  },
  variants: {
    orientation: {
      vertical: {
        root: "checkbox-group--vertical",
      },
      horizontal: {
        root: "checkbox-group--horizontal",
      },
    },
  },
  defaultVariants: {
    orientation: "vertical",
  },
});

export type CheckboxGroupVariants = VariantProps<typeof checkboxGroupVariants>;

"use client";

import { createContext, useContext } from "react";

import { checkboxGroupVariants } from "./checkbox-group.variants";

export type CheckboxGroupContext = {
  slots: ReturnType<typeof checkboxGroupVariants>;
};

export const CheckboxGroupContext = createContext<CheckboxGroupContext | null>(null);

export const useCheckboxGroupContext = () => {
  const context = useContext(CheckboxGroupContext);
  return context ?? { slots: checkboxGroupVariants() };
};

.checkbox-group {
  @apply flex text-foreground;
}

.checkbox-group--vertical {
  @apply flex-col items-start gap-2;
}

.checkbox-group--horizontal {
  @apply flex-row items-center gap-4;
}

import { CheckboxGroupRoot } from "./checkbox-group";

export const CheckboxGroup = {
  Root: CheckboxGroupRoot,
};

export { CheckboxGroupRoot };

export type { CheckboxGroupProps } from "./checkbox-group";
export { CheckboxGroupContext, useCheckboxGroupContext } from "./checkbox-group.context";
export { type CheckboxGroupVariants, checkboxGroupVariants } from "./checkbox-group.variants";
